drills.solutionHead:
// ─────────────────────────────────────────────────────────────────────────
//  01 · route template matching★★☆ core
//  concepts: route templates · constraints · case-insensitive literals
// ─────────────────────────────────────────────────────────────────────────
//
//  Constraints decide whether a route matches, which is why a mismatch is a 404.

using static Bootcamp.Check;

Dictionary<string, string>? Match(string template, string path)
{
    var cut = path.IndexOf('?');
    if (cut >= 0) path = path[..cut];
    if (path.Length > 1 && path.EndsWith('/')) path = path[..^1];
    var want = template.TrimStart('/').Split('/');
    var have = path.TrimStart('/').Split('/');
    if (want.Length != have.Length) return null;
    var values = new Dictionary<string, string>();
    for (var i = 0; i < want.Length; i++)
    {
        var w = want[i];
        var h = have[i];
        if (w.StartsWith('{') && w.EndsWith('}'))
        {
            if (h.Length == 0) return null;
            var inner = w[1..^1];
            var colon = inner.IndexOf(':');
            var name = colon < 0 ? inner : inner[..colon];
            var constraint = colon < 0 ? null : inner[(colon + 1)..];
            var value = Uri.UnescapeDataString(h);
            if (constraint == "int" && !int.TryParse(value, System.Globalization.NumberStyles.AllowLeadingSign, System.Globalization.CultureInfo.InvariantCulture, out _)) return null;
            values[name] = value;
        }
        else if (!string.Equals(w, h, StringComparison.OrdinalIgnoreCase))
        {
            return null;
        }
    }
    return values;
}

drills.tests:
// ──────────────────────────── tests ──────────────────────────────────────

Test("captures parameters, ignores the query string and literal case", () =>
{
    var m = Match("/orders/{id:int}", "/Orders/42?expand=lines");
    Ok(m is not null, "should match");
    Eq(m!["id"], "42");
});

Test("an int constraint that fails means no match", () =>
{
    Ok(Match("/orders/{id:int}", "/orders/abc") is null, "abc is not an int");
    Ok(Match("/orders/{id:int}", "/orders/1.5") is null, "1.5 is not an int");
});

Test("several parameters, decoded", () =>
{
    var m = Match("/users/{user}/files/{name}", "/users/ana/files/caf%C3%A9.txt");
    Eq(m!["user"], "ana");
    Eq(m["name"], "café.txt");
});

Test("segment count and literals must agree", () =>
{
    Ok(Match("/orders/{id}", "/orders") is null, "too few segments");
    Ok(Match("/orders/{id}", "/orders/1/lines") is null, "too many segments");
    Ok(Match("/orders/{id}", "/invoices/1") is null, "literal differs");
});

Test("a trailing slash is tolerated, an empty segment is not (boundary)", () =>
{
    Eq(Match("/orders/{id:int}", "/orders/7/")!["id"], "7");
    Ok(Match("/orders/{id}/lines", "/orders//lines") is null, "empty parameter");
});

drills.explanation:
Normalise the path, compare segment counts, then treat each template segment as either a literal (case-insensitive compare) or a parameter (capture, decode, apply the constraint):

```csharp
if (w.StartsWith('{') && w.EndsWith('}'))
{
    // name and optional constraint from inside the braces
    var value = Uri.UnescapeDataString(h);
    if (constraint == "int" && !int.TryParse(value, NumberStyles.AllowLeadingSign, CultureInfo.InvariantCulture, out _)) return null;
    values[name] = value;
}
else if (!string.Equals(w, h, StringComparison.OrdinalIgnoreCase)) return null;
```

Returning null (no match) for a failed constraint is exactly why ASP.NET Core answers such a request with 404: no endpoint matched.
